// Generate CSV
function escapeCsv(val) {
  if (val == null) return "";
  const s = String(val).replace(/"/g, '""');
  return `"${s}"`;
}

const headers = ["Full Name", "Hospital or Practice Affiliation", "Specialty Focus", "Note Confirming ACL/Meniscus Mention", "Direct Profile Link"];
const csvRows = [headers.map(escapeCsv).join(",")];
for (const s of surgeons) {
  csvRows.push([
    escapeCsv(s.name),
    escapeCsv(s.affiliation),
    escapeCsv(s.specialty),
    escapeCsv(s.note),
    escapeCsv(s.link)
  ].join(","));
}
const csvContent = csvRows.join("\r\n");

// Write downloadable file
